tool.command:
## Exit status 1 is a completed check that failed; the status is kept to report it.
#if $input.ext in ['yaml', 'json', 'jsonld']
    #set $check = 'metadata validated against the schema'
    bioheaders validate --from '$input.ext' '$input' > messages.txt 2>&1 && status=0 || status=\$? ;
#else
    @SET_TYPE@
    #set $check = 'header validated against the schema and checksum verified'
    bioheaders verify --type '$type' '$input' > messages.txt 2>&1 && status=0 || status=\$? ;
#end if
cat messages.txt &&
if [ "\$status" -eq 0 ]; then result=PASSED; else result=FAILED; fi &&
{
    echo 'FAIR-bioHeaders verify (fair-bioheaders @TOOL_VERSION@)' ;
    echo "Dataset: \$(cat '$name_file')" ;
    echo 'Check: $check' ;
    echo "Result: \$result" ;
    echo ;
    cat messages.txt ;
} > '$report' &&
#if $on_failure == 'fail'
    [ "\$status" -eq 0 ]
#else
    ## Any status other than 0 or 1 stops the job.
    [ "\$status" -le 1 ]
#end if
